class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

def build_tree(nodes):
    root = Node(nodes[0])
    queue = [root]
    i = 1
    while i < len(nodes):
        node = queue.pop(0)
        node.left = Node(nodes[i])
        queue.append(node.left)
        i += 1
        if i < len(nodes):
            node.right = Node(nodes[i])
            queue.append(node.right)
            i += 1
    return root

def dfs(node, parent_value):
    if node.left:
        node.left.value = abs(node.value - parent_value)
        dfs(node.left, node.value)
    if node.right:
        node.right.value = abs(node.value - parent_value)
        dfs(node.right, node.value)

def closest(node):
    if node.left:
        return min(node.left.value, node.right.value)
    return node.value

def farthest(node):
    if node.left:
        return max(node.left.value, node.right.value)
    return node.value

