def min_time_to_unlock_all_cars(M, N, C):
    directions = [(1, 0)]  # Only down direction initially
    queue = deque()
    visited = set()
    time = 0

    # Initialize the queue with all positions that have a car
    for i in range(M):
        for j in range(N):
            if C[i][j] == 'P':
                queue.append((i, j))
                visited.add((i, j))

    while queue:
        size = len(queue)
        for _ in range(size):
            x, y = queue.popleft()
            if x == M - 1 and all(C[i][y] == 'N' for i in range(x, M)):
                return time

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < M and 0 <= ny < N and (nx, ny) not in visited and C[nx][ny] == 'P':
                    queue.append((nx, ny))
                    visited.add((nx, ny))

        time += 1
        if time % 2 == 0:
            directions.append((0, -1))  # Add left direction for even levels
        else:
            directions.append((0, 1))  # Add right direction for odd levels

    return time

