MOD = 10**9 + 7

def factorial(n):
    if n == 0:
        return 1
    result = 1
    for i in range(1, n + 1):
        result = (result * i) % MOD
    return result

def inverse_factorial(n):
    return pow(factorial(n), MOD - 2, MOD)

def count_anagrams(s):
    count = Counter(s)
    numerator = factorial(len(s))
    denominator = 1
    for value in count.values():
        denominator = (denominator * inverse_factorial(value)) % MOD
    return (numerator * denominator) % MOD

