def get_neighbors(board, empty_pos):
    neighbors = []
    i, j = empty_pos
    if i > 0 and is_prime(board[i][j] + board[i-1][j]):
        neighbors.append((i-1, j))
    if i < 2 and is_prime(board[i][j] + board[i+1][j]):
        neighbors.append((i+1, j))
    if j > 0 and is_prime(board[i][j] + board[i][j-1]):
