    return neighbors

def solve_puzzle(board):
    goal = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
    empty_pos = None
    for i in range(3):
        for j in range(3):
            if board[i][j] == 0:
                empty_pos = (i, j)
                break
        if empty_pos:
            break

    queue = deque([(board, 0, empty_pos)])
    visited = set()
    visited.add(tuple(map(tuple, board)))

    while queue:
        current_board, steps, empty_pos = queue.popleft()
        if current_board == goal:
            return steps

        for neighbor in get_neighbors(current_board, empty_pos):
            new_board = [row[:] for row in current_board]
