def find_triple_tree_decomposition(N, edges):
    if (N - 1) % 3 != 0:
        return "NO"

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def dfs(node, parent, decomposition):
        if len(graph[node]) <= 2:
            return decomposition
        for neighbor in graph[node]:
            if neighbor != parent:
                if len(decomposition) >= (N - 1) // 3:
                    return decomposition
                decomposition.append((node, neighbor, graph[node][0], graph[node][1]))
                return dfs(neighbor, node, decomposition)
        return decomposition

