from collections import defaultdict

def find(parent, i):
    if parent[i] == i:
        return i
    parent[i] = find(parent, parent[i])
    return parent[i]

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)
    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def is_dag(graph, n):
    parent = list(range(n))
    rank = [0] * n
    for u, v in graph:
        u -= 1
        v -= 1
        if find(parent, u) == find(parent, v):
            return False
        union(parent, rank, u, v)
    return True

