    return factors

def lcm(x, y):
    return x * y // gcd(x, y)

def solve(n):
    factors = prime_factors(n)
    divisors = sorted(set(factors))
    initial_order = [1] + divisors + [1]
    moves = 0
    for i in range(1, len(initial_order) - 1):
