def min_steps(N, K, A):
    queue = deque([0])
    steps = [-1] * N
    steps[0] = 0
    current_max = 0

    while queue:
        current = queue.popleft()
        if current >= current_max:
            current_max = current + K
        for i in range(max(current + 1, current_max), min(N, current + K + 1)):
