def is_stable_rocket(coefficients: List[int]) -> bool:
    rows = [coefficients]
    n = len(coefficients)

    for r in range(1, n):
        new_row = []
        for n in range(r + 1):
            if r == 1:
                new_row.append(coefficients[n])
            else:
                a = rows[r-1][0] * coefficients[n+1] if n+1 < n else 0
                b = rows[r-2][0] * coefficients[n+1] if n+1 < n else 0
                new_row.append(a - b)
        rows.append(new_row)

    for row in rows:
        if row[0] == 0 and any(x != 0 for x in row[1:]):
            return False

    return True

