import sys
from collections import defaultdict

def euler_tour(n, edges, tour):
    parent = [0] * (n + 1)
    time = [0] * (n + 1)
    pos = [0] * (n + 1)
    tour_list = []

    def dfs(node, prev):
        nonlocal time
        time[node] = len(tour_list)
        pos[node] = len(tour_list)
        tour_list.append(node)
        for nei in edges[node]:
            if nei != prev:
                dfs(nei, node)
        tour_list.append(node)

    dfs(1, 0)

    for i in range(1, n + 1):
        parent[i] = tour_list[pos[i] + 1]

    return parent, time, tour_list

def solve(n, queries, parent, time, tour):
    lca_table = [[0] * 20 for _ in range(n + 1)]

    def build_lca(n):
        for i in range(1, n + 1):
            lca_table[i][0] = parent[i]
            for j in range(1, 20):
                if i >= pow(2, j):
                    lca_table[i][j] = lca_table[lca_table[i][j - 1]][j - 1]

    def get_lca(a, b):
        if a == b:
            return a
        if a < b:
            a, b = b, a
        diff = 19
        while diff >= 0:
            if b >= pow(2, diff):
                b = lca_table[b][diff]
                diff -= 1
        if a == b:
            return a
        for i in range(19, -1, -1):
            if lca_table[a][i] != lca_table[b][i]:
                a = lca_table[a][i]
                b = lca_table[b][i]
        return parent[a]

    results = []
    for query in queries:
        a, da, b, db = query
        if (time[a] - time[b]) % (2 * db) != 0:
            results.append(-1)
            continue
        dist_ab = (time[a] - time[b]) // (2 * db)
        lca = get_lca(a, b)
        if (time[a] + time[b] - 2 * time[lca]) % (2 * da) != 0:
            results.append(-1)
            continue
        dist_alca = (time[a] + time[b] - 2 * time[lca]) // (2 * da)
        if dist_alca == dist_ab:
            results.append(tour[pos[a] + dist_ab - 1])
        else:
            results.append(-1)

    return results

