def manhattan_distance_pairs(N, M, grid):
    houses = []
    for i in range(N):
        for j in range(M):
            if grid[i][j] == '1':
                houses.append((i, j))

    counts = [0] * (N + M - 1)
    for i, (x1, y1) in enumerate(houses):
        for j, (x2, y2) in enumerate(houses[i+1:]):
            dist = abs(x1 - x2) + abs(y1 - y2)
            if dist > N + M - 2:
                break
            counts[dist-1] += 1

    return counts

