import sys
from typing import List

def lca(tree: List[List[int]], n: int, query_nodes: List[int]) -> int:
    ancestors = [set() for _ in range(n + 1)]
    for node in range(1, n + 1):
        for ancestor in tree[node]:
            ancestors[ancestor].add(node)

    def find_lca(a: int, b: int) -> int:
        if a not in ancestors[b] and b not in ancestors[a]:
            return min(a, b)
        if a in ancestors[b]:
            return a
        return b

    return find_lca(*query_nodes)

def solve(n: int, special_nodes: List[int], costs: List[int], queries: List[List[int]], w: int) -> List[int]:
    tree = [[] for _ in range(n + 1)]
    for i in range(1, n):
        tree[i + 1].append(int(sys.stdin.readline()))
        tree[int(sys.stdin.readline())].append(i + 1)

    lca_nodes = [lca(tree, n, query) for query in queries]

    dp = [[[0] * (w + 1) for _ in range(2)] for _ in range(n + 1)]
    for node in range(1, n + 1):
        dp[node][0][0] = costs[node - 1]
        dp[node][1][0] = -costs[node - 1]

    for node in range(1, n + 1):
        for special in special_nodes:
            if node == special:
                continue
            parent = lca_nodes[special - 1]
            for cost in range(w + 1):
                dp[node][0][cost] = max(dp[node][0][cost], dp[parent][0][cost - 1] + costs[node - 1])
                dp[node][1][cost] = max(dp[node][1][cost], dp[parent][1][cost - 1] - costs[node - 1])

    return [max(dp[query][0][w], dp[query][1][w]) for query in queries]

