    h.sort(reverse=True)
    left, right = 0, n
    result = -1

    while left <= right:
        mid = (left + right) // 2
        if sum(h[:mid]) >= k:
            right = mid - 1
            result = mid
        else:
            left = mid + 1

    if result == -1 or sum(h[result:]) < k:
        return -1
    else:
        return result + n - result

