    divisors = get_divisors(factors)

    n_divisors = len(divisors)
    adj_matrix = [[0] * n_divisors for _ in range(n_divisors)]

    for i in range(n_divisors):
        for j in range(i + 1, n_divisors):
            if gcd(divisors[i], divisors[j]) != 1:
                adj_matrix[i][j] = 1
                adj_matrix[j][i] = 1

    def bfs(start):
        visited = [False] * n_divisors
        queue = [(start, 0)]
        visited[start] = True

        while queue:
            current, steps = queue.pop(0)
            for neighbor in range(n_divisors):
