class UnionFind:
    def __init__(self, n):
        self.root = list(range(n))
        self.rank = [0] * n
        self.blocked = [False] * n

    def find(self, x):
        if self.root[x] != x:
            self.root[x] = self.find(self.root[x])
        return self.root[x]

    def union(self, x, y):
        x_root, y_root = self.find(x), self.find(y)
        if x_root == y_root:
            if (not self.blocked[x_root]) and (not self.blocked[y_root]):
                self.blocked[x_root] = True
            return
        if self.rank[x_root] < self.rank[y_root]:
            x_root, y_root = y_root, x_root
        self.root[y_root] = x_root
        if (not self.blocked[x_root]) and (not self.blocked[y_root]):
            self.blocked[x_root] = self.blocked[y_root] = True

    def connected(self, x, y):
        return self.find(x) == self.find(y)

