def solve_palindrome(s):
    count = 0
    for c in s:
        if c == '.':
            count += 1

    if (len(s) % 2 == 0 and count == 0) or (len(s) % 2 != 0 and count == 1):
        return -1

    half = ''.join([c for c in s if c != '.'])
    if len(half) % 2 == 0:
        half = half[:len(half)//2]
    else:
        half = half[:len(half)//2 + 1]

    for i in range(len(half) - 1, -1, -1):
        if half[i] < half[len(half) - i - 1]:
            half = half[:len(half) - i] + chr(ord(half[i]) + 1) + half[len(half) - i:]

    result = half + half[::-1]
    for i in range(len(s)):
        if s[i] == '.':
            result = result[:i] + result[i].upper() + result[i + 1:]

    return result if '.' not in result else -1

